import time
from neo4j import driver

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            if metadata:
                tx.metadata(metadata)
            if timeout:
                start_time = time.time()
                while time.time() - start_time < timeout:
                    result = func(tx)
                    if result:
                        return result
                    time.sleep(0.1)
                raise Exception("Transaction timed out")
            return func(tx)
        return wrapper
    return decorator

