from collections import defaultdict

def _legacy_mergeOrderings(orderings):
    def merge_elements(element, start_ordering):
        start_index = start_ordering.index(element)
        for order in orderings:
            if order.index(element) > start_index:
                order.insert(start_index, element)
    merged_orderings = []
    for ordering in orderings:
        if ordering:
            merged_orderings.extend(ordering)
    element_to_ordering = defaultdict(list)
    for ordering in orderings:
        for element in ordering:
            element_to_ordering[element].append(ordering)
    for element, orderings in element_to_ordering.items():
        if orderings:
            merge_elements(element, min(orderings, key=lambda x: x.index(element)))
    return merged_orderings

