    for key, value in nodes:
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            merged_data[key] = merge_dict(merged_data.get(key, {}), value)
        else:
            merged_data[key] = value

    return [((k,), K) for k, K in merged_data.items()]

