from rdflib import Graph, URIRef, Node
from typing import Optional

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """

    if roots is None:
        roots = set()

    for node in graph:
        in_ns = node.namespace

        if in_ns == "http://www.w3.org/1999/02/22-rdf-syntax-ns#":
            p_node = property(graph, prop, node)
            if not isinstance(p_node, Node):
                continue

            if p_node.has_uri(rdflib.RDFS.subClassOf) and node.is_thing():
                roots.add(node)
                for sibling in graph.objects(node, p_node):
                    if sibling.has_uri(rdflib.RDFS.subClassOf):
                        find_roots(graph, prop, roots)

    return roots

