import importlib.util
import logging
from typing import List, Optional, Dict

_log = logging.getLogger(__name__)
def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, str]] = None, resolve_env: bool = True) -> (Dict[str, Dict], List[logging.LogRecord]):
    config_dict = {}
    errors = []
    for filename in config_filenames:
        try:
            spec = importlib.util.spec_from_file_location(filename, filename)
            if spec is not None:
                config_module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(config_module)
                config_dict[filename] = config_module.config
                if overrides is not None:
                    config_dict[filename].update(overrides)
        except Exception as e:
            if resolve_env or logging.ERROR - 10 > e.__level__:
                _log.error(f"Failed to load configuration from {filename}, {e}")
                errors.append(logging.LoggerAdapter(logging.getLogger(), {})[e.__level__](str(e)))
            else:
                raise

    return config_dict, errors

