from collections import namedtuple

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    Histogram = namedtuple('Histogram', field_names)
    Graph = namedtuple('Graph', field_names)

    assert len(hist.bin_bounds) >= 2, "Histogram must have at least two bins"

    # Initialize the graph with zeros
    graph = Graph(*(0.0,) * len(field_names))

    for i, bin_content in enumerate(hist.values):
        if make_value:
            valued = make_value(bin_content)
        else:
            valued = bin_content
        x = (hist.bin_bounds[i] + hist.bin_bounds[i+1]) / 2
        value_x, value_y = valued

        if get_coordinate == "left":
            graph = graph._replace(x=x, y=value_y)
        elif get_coordinate == "right":
            graph = graph._replace(x=x + hist.bin_size / 2, y=value_y)
        elif get_coordinate == "middle":
            graph = graph._replace(x=x + hist.bin_size / 4, y=value_y)
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if scale is True:
        graph = graph._replace(x=graph.x * hist.bin_size, y=graph.y * hist.bin_size)

    return graph

