from zope.interface import implementer
from.zope.interface import Interface
from zope.interface import Invalid

@implementer(Interface)
class ExampleInterface(Interface):
    def method1():
        pass

    def method2():
        pass

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import verify
    from zope.interface import getInterfaceSupport

    if tentative:
        return

    # Check if the interface is provided by the candidate
    if not iface.providedBy(candidate):
        raise Invalid(
            'Candidate does not provide the interface defined by <zope.interface.implementer>'

    # Get the interface support for the candidate
    interface_support = getInterfaceSupport(candidate)

    # Check if all methods in the interface are provided by the candidate
    for method_name in iface.implementedBy():
        if method_name not in interface_support or not hasattr(candidate, method_name):
            raise Invalid(f'Candidate does not provide method: {method_name}')

    # Check if all attributes in the interface are defined in the candidate
    for attr_name in iface.implementedBy():
        if attr_name not in dir(candidate):
            raise Invalid(f'Candidate does not define attribute: {attr_name}')

    return True

