import abc

class abc(type):
    def __instancecheck__(cls, obj):
        if cls.__name__ == 'abstractmethods':
            return obj if python_version < '3.2' else isinstance(obj, type)
        elif hasattr(obj, '__subclasscheck__'):
            return super().__subclasscheck__(obj)
        elif cls.__name__ == 'ABC':
            return super().__subclasscheck__(obj)
        elif hasattr(obj.__class__, '__metaclass__') and obj.__class__.__metaclass__ == abc.ABCMeta:
            return super().__subclasscheck__(obj.__class__)
        elif isinstance(obj, abc.ABCMeta) and cls.__name__ == 'abc':
            return super().__subclasscheck__(obj)
        elif obj.__class__ not in cls.__subclasses__:
            return False
        return super().__subclasscheck__(obj)

