import json

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    webfinger_dict = None

    # Check for XRD (old) format first
    try:
        xrd_dict = json.loads(document)

        if 'WebFinger' in xrd_dict:
            schema = xrd_dict['WebFinger']['schema']
            if schema == 'http://diaspora.org/xrd/0.1':
                webfinger_dict = xrd_dict
    except json.JSONDecodeError:
        pass

    # Check for JSON (new) format
    if webfinger_dict is None:
        try:
            webfinger_dict = json.loads(document)
        except json.JSONDecodeError:
            pass

    return webfinger_dict

