import requests
from bs4 import BeautifulSoup
import json

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    url = f"https://www.diaspora.cafe/webfinger/{handle}"
    response = requests.get(url)
    if response.status_code == 200:
        webpage = response.text
        soup = BeautifulSoup(webpage, 'html.parser')
        data = soup.find('link', rel='http://webfinger.net/rel/directory')
        if data is not None:
            owner = data['href'].split(':')[2]
            contacts = data.find_next_sibling('li').text
            profile = data.find_next_sibling('li').find_next_sibling('li').text
            return {"owner": owner, "contacts": contacts, "profile": profile}
        else:
            return {"error": "Failed to retrieve Diaspora accounts"}
    else:
        return {"error": "Failed to retrieve webfinger response"}

